contracts/CampaignVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

contract CampaignVault is Ownable {
    using SafeERC20 for IERC20;

    struct Campaign {
        address advertiser;
        IERC20 token;
        uint256 funded;
        uint256 reserved;
        uint256 paid;
        bool active;
    }

    struct Agreement {
        uint256 campaignId;
        address publisher;
        uint256 allocationCap;
        uint256 settled;
        bool active;
    }

    address public settlementOperator;
    uint256 public nextCampaignId;
    uint256 public nextAgreementId;
    mapping(uint256 => Campaign) public campaigns;
    mapping(uint256 => Agreement) public agreements;
    mapping(address => mapping(address => uint256)) public claimable;

    event CampaignCreated(uint256 indexed campaignId, address indexed advertiser, address indexed token, uint256 amount);
    event AgreementCreated(uint256 indexed agreementId, uint256 indexed campaignId, address indexed publisher, uint256 cap);
    event SettlementRecorded(uint256 indexed agreementId, uint256 amount);
    event Claimed(address indexed publisher, address indexed token, uint256 amount);

    constructor(address initialOwner, address initialSettlementOperator) Ownable(initialOwner) {
        settlementOperator = initialSettlementOperator;
    }

    function setSettlementOperator(address operator) external onlyOwner {
        settlementOperator = operator;
    }

    function createCampaign(address token, uint256 amount) external returns (uint256 campaignId) {
        require(token != address(0) && amount > 0, "invalid campaign");
        campaignId = ++nextCampaignId;
        campaigns[campaignId] = Campaign({ advertiser: msg.sender, token: IERC20(token), funded: amount, reserved: 0, paid: 0, active: true });
        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);
        emit CampaignCreated(campaignId, msg.sender, token, amount);
    }

    function createAgreement(uint256 campaignId, address publisher, uint256 allocationCap) external returns (uint256 agreementId) {
        Campaign storage campaign = campaigns[campaignId];
        require(campaign.advertiser == msg.sender && campaign.active, "not campaign owner");
        require(publisher != address(0) && allocationCap > 0, "invalid agreement");
        require(campaign.funded - campaign.reserved - campaign.paid >= allocationCap, "insufficient escrow");
        campaign.reserved += allocationCap;
        agreementId = ++nextAgreementId;
        agreements[agreementId] = Agreement({ campaignId: campaignId, publisher: publisher, allocationCap: allocationCap, settled: 0, active: true });
        emit AgreementCreated(agreementId, campaignId, publisher, allocationCap);
    }

    function recordSettlement(uint256 agreementId, uint256 amount) external {
        require(msg.sender == settlementOperator, "not settlement operator");
        Agreement storage agreement = agreements[agreementId];
        require(agreement.active && amount > 0, "invalid settlement");
        require(agreement.settled + amount <= agreement.allocationCap, "allocation exceeded");
        Campaign storage campaign = campaigns[agreement.campaignId];
        agreement.settled += amount;
        campaign.reserved -= amount;
        campaign.paid += amount;
        claimable[agreement.publisher][address(campaign.token)] += amount;
        emit SettlementRecorded(agreementId, amount);
    }

    function claim(address token) external {
        uint256 amount = claimable[msg.sender][token];
        require(amount > 0, "nothing claimable");
        claimable[msg.sender][token] = 0;
        IERC20(token).safeTransfer(msg.sender, amount);
        emit Claimed(msg.sender, token, amount);
    }

    function withdrawUnreserved(uint256 campaignId, uint256 amount) external {
        Campaign storage campaign = campaigns[campaignId];
        require(campaign.advertiser == msg.sender, "not campaign owner");
        uint256 available = campaign.funded - campaign.reserved - campaign.paid;
        require(amount <= available, "amount exceeds available escrow");
        campaign.funded -= amount;
        campaign.token.safeTransfer(msg.sender, amount);
    }
}

